#!/usr/bin/env python3
"""Offline GitHub Actions workflow inventory.

This intentionally is not a security assessor. It records permissions declarations
and action references with source evidence for a reviewing agent.

Supported YAML syntax: ordinary GitHub Actions YAML mappings/lists, quoted or
plain scalar values, comments, nested mappings/lists, and flow-map ``{}`` for
permissions. It does not evaluate anchors/aliases, merge keys, block scalars,
expressions, or custom YAML tags. It uses only Python's standard library; no
network access or workflow execution occurs.
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path
from typing import Any

KEY_RE = re.compile(r"^(?P<indent> *)(?P<key>[^:#][^:]*?):(?:[ \t]*(?P<value>.*?))?[ \t]*$")
LIST_RE = re.compile(r"^(?P<indent> *)-[ \t]*(?P<rest>.*?)[ \t]*$")


def strip_comment(value: str) -> str:
    quoted = None
    escaped = False
    for i, char in enumerate(value):
        if escaped:
            escaped = False
        elif char == "\\" and quoted == '"':
            escaped = True
        elif char in "'\"":
            quoted = None if quoted == char else (char if quoted is None else quoted)
        elif char == "#" and quoted is None and (i == 0 or value[i - 1].isspace()):
            return value[:i].rstrip()
    return value.rstrip()


def scalar(value: str) -> Any:
    value = strip_comment(value).strip()
    if value == "":
        return None
    if value == "{}":
        return {}
    if value in ("[]",):
        return []
    if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
        return value[1:-1]
    if value.lower() in ("true", "false"):
        return value.lower() == "true"
    return value


def key_value(line: str):
    match = KEY_RE.match(line)
    if not match:
        return None
    return len(match.group("indent")), match.group("key").strip(), match.group("value") or ""


def nonempty_lines(lines):
    for number, raw in enumerate(lines, 1):
        text = raw.rstrip("\r\n")
        if not text.strip() or text.lstrip().startswith("#") or text.strip() in ("---", "..."):
            continue
        yield number, text


def permission_value(value: str, line: int, raw: str) -> dict[str, Any]:
    clean = strip_comment(value).strip()
    if clean == "{}":
        return {"state": "explicit_empty", "values": {}, "line": line, "evidence": raw.strip()}
    values = {}
    if clean:
        values["_raw"] = scalar(clean)
    return {"state": "declared", "values": values, "line": line, "evidence": raw.strip()}


def inventory_file(path: Path, root: Path) -> dict[str, Any]:
    lines = path.read_text(encoding="utf-8").splitlines()
    rows = list(nonempty_lines(lines))
    relative = path.relative_to(root).as_posix()
    workflow_permissions = {"state": "omitted", "values": {}, "line": None, "evidence": None}
    jobs: list[dict[str, Any]] = []
    action_uses: list[dict[str, Any]] = []

    # Top-level keys are the non-comment keys at the smallest indentation.
    top_indent = min((len(text) - len(text.lstrip(" ")) for _, text in rows), default=0)
    jobs_start = None
    jobs_indent = None
    for number, text in rows:
        parsed = key_value(text)
        if not parsed:
            continue
        indent, key, value = parsed
        if indent == top_indent and key == "permissions":
            workflow_permissions = permission_value(value, number, text)
        if indent == top_indent and key == "jobs":
            jobs_start, jobs_indent = number, indent

    # Locate direct job entries under jobs, then inspect their immediate permissions
    # and all uses entries until the next peer job. Indentation is sufficient for
    # ordinary Actions workflow YAML and preserves exact source line evidence.
    if jobs_start is not None:
        in_jobs = False
        current = None
        current_indent = None
        for number, text in rows:
            parsed = key_value(text)
            if not parsed:
                continue
            indent, key, value = parsed
            if number == jobs_start:
                in_jobs = True
                continue
            if not in_jobs:
                continue
            if indent <= jobs_indent:
                break
            if current is None or (indent == jobs_indent + 2 and key not in ("permissions", "uses")):
                if indent == jobs_indent + 2:
                    current = {
                        "name": key,
                        "line": number,
                        "evidence": text.strip(),
                        "permissions": {"state": "omitted", "values": {}, "line": None, "evidence": None},
                    }
                    jobs.append(current)
                    current_indent = indent
                    if key == "uses":
                        action_uses.append({"job": None, "kind": "reusable_workflow", "reference": scalar(value), "line": number, "evidence": text.strip()})
                    continue
            if current is None:
                continue
            if indent == current_indent + 2 and key == "permissions":
                current["permissions"] = permission_value(value, number, text)
            if key == "uses":
                action_uses.append({
                    "job": current["name"],
                    "kind": "action_or_reusable_workflow",
                    "reference": scalar(value),
                    "line": number,
                    "evidence": text.strip(),
                })

    # A second, syntax-neutral pass records every uses key in the file, including
    # nested steps and reusable-workflow jobs. It avoids missing unusual but valid
    # step formatting; duplicates are removed by line.
    seen_lines = {item["line"] for item in action_uses}
    for number, text in rows:
        parsed = key_value(text)
        if parsed and parsed[1] == "uses" and number not in seen_lines:
            indent, _, value = parsed
            job = None
            for candidate in reversed(jobs):
                if candidate["line"] < number:
                    job = candidate["name"]
                    break
            action_uses.append({"job": job, "kind": "action_or_reusable_workflow", "reference": scalar(value), "line": number, "evidence": text.strip()})
    action_uses.sort(key=lambda item: item["line"])

    return {"path": relative, "workflow_permissions": workflow_permissions, "jobs": jobs, "action_uses": action_uses, "line_count": len(lines)}


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print(f"usage: {Path(argv[0]).name} WORKFLOW_DIRECTORY OUTPUT_JSON", file=sys.stderr)
        return 2
    root = Path(argv[1]).resolve()
    output = Path(argv[2])
    if not root.is_dir():
        print(f"error: workflow directory does not exist: {root}", file=sys.stderr)
        return 2
    files = sorted(p for p in root.rglob("*") if p.is_file() and p.suffix.lower() in (".yml", ".yaml"))
    document = {
        "schema": "github-actions-workflow-inventory/v1",
        "offline": True,
        "yaml_parser": "line-oriented standard-library subset; see workflow-inventory.md",
        "workflow_directory": str(root),
        "files": [inventory_file(path, root) for path in files],
    }
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(document, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"inventoried {len(files)} YAML file(s) -> {output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

